import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_list(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

def is_good_set(U):
    if len(U) < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1
    for combination in combinations(U, 3):
        if gcd_list(combination) != 1:
            return False

    # Condition 2: For any two distinct elements x, y, there exists another element z in U (z != x, z != y) such that z | xy
    for x, y in combinations(U, 2):
        xy = x * y
        found_distinct_divisor = False
        for z in U:
            if z != x and z != y and xy % z == 0:
                found_distinct_divisor = True
                break

        if not found_distinct_divisor:
            return False
    return True

def is_good_number(m):
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i*i != m:
                divs.append(m//i)
    divs = sorted(list(set(divs)))

    # Iterate over subsets U of divisors such that product(U) = m and |U| >= 3

    found = False
    for i in range(1, 1 << len(divs)):
        U = []
        product = 1
        for j in range(len(divs)):
            if (i >> j) & 1:
                d = divs[j]
                U.append(d)
                product *= d

        if len(U) >= 3 and product == m:
            if is_good_set(U):
                found = True
                break
    return found

